{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Prepare Cell Culture",
      "instruction": "Seed neural stem cells (Cor3-1) at a density of 1.5x10^6 in 10 cm dishes with Complete media.",
      "expected_result": "Cells are seeded and ready for growth in a suitable environment."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Maintain Cell Culture",
      "instruction": "Regularly monitor and maintain cells with appropriate growth factors.",
      "expected_result": "Cells are healthy and proliferating in culture."
    },
    {
      "id": "S3",
      "task_id": "T2",
      "title": "Induce Neuronal Differentiation",
      "instruction": "Transfer cells to priming and differentiation media to initiate neuronal differentiation.",
      "expected_result": "Cells begin to differentiate into neuronal cells."
    },
    {
      "id": "S4",
      "task_id": "T3",
      "title": "Transfect P19 Cells",
      "instruction": "Transfect P19 cells with plasmids using Lipofectamine 2000 according to the manufacturer's instructions.",
      "expected_result": "P19 cells are successfully transfected with plasmids."
    },
    {
      "id": "S5",
      "task_id": "T6",
      "title": "Wash Cells",
      "instruction": "Wash cells once with room temperature PBS to remove media.",
      "expected_result": "Cells are washed and ready for collection."
    },
    {
      "id": "S6",
      "task_id": "T6",
      "title": "Collect Cells",
      "instruction": "Use a cell scraper to collect cells in ice-cold PBS and transfer to a microcentrifuge tube.",
      "expected_result": "Cells are collected in a tube for further processing."
    },
    {
      "id": "S7",
      "task_id": "T6",
      "title": "Centrifuge to Pellet Cells",
      "instruction": "Centrifuge the collected cells at 130xg at 4°C for 3 minutes to pellet them.",
      "expected_result": "Cell pellet is formed at the bottom of the tube."
    },
    {
      "id": "S8",
      "task_id": "T6",
      "title": "Lyse Cell Pellet",
      "instruction": "Lyse the cell pellet with ice-cold E1 buffer at a ratio of 5 volumes of buffer to 1 volume of pellet.",
      "expected_result": "Cell lysate is prepared for fractionation."
    },
    {
      "id": "S9",
      "task_id": "T6",
      "title": "Centrifuge for Cytoplasm Fraction",
      "instruction": "Centrifuge the lysate at 1,100xg at 4°C for 2 minutes to separate the cytoplasm fraction.",
      "expected_result": "Cytoplasm fraction is collected in a fresh tube."
    },
    {
      "id": "S10",
      "task_id": "T6",
      "title": "Resuspend and Centrifuge for Nucleus Fraction",
      "instruction": "Resuspend the pellet in E1 buffer, centrifuge at 1,100xg at 4°C for 2 minutes, and discard supernatant.",
      "expected_result": "Nuclear fraction is isolated for further analysis."
    },
    {
      "id": "S11",
      "task_id": "T5",
      "title": "Prepare for Western Blot",
      "instruction": "Resuspend the nuclear pellet in ice-cold E3 buffer and sonicate for protein extraction.",
      "expected_result": "Protein lysate is prepared for Western blot analysis."
    },
    {
      "id": "S12",
      "task_id": "T5",
      "title": "Centrifuge and Collect Supernatant",
      "instruction": "Centrifuge the protein lysate at 16,000xg at 4°C for 10 minutes and transfer the supernatant to fresh tubes.",
      "expected_result": "Supernatant containing proteins is ready for quantification."
    },
    {
      "id": "S13",
      "task_id": "T5",
      "title": "Measure Protein Concentration",
      "instruction": "Measure the protein concentration using a suitable assay kit and prepare for Western blotting.",
      "expected_result": "Protein concentration is determined for subsequent analysis."
    },
    {
      "id": "S14",
      "task_id": "T7",
      "title": "Prepare for Pull Down Assay",
      "instruction": "Resuspend the pellet in ice-cold E3 (benzonase) buffer and detach the pellet by flicking the tube.",
      "expected_result": "Pellet is resuspended and ready for benzonase treatment."
    },
    {
      "id": "S15",
      "task_id": "T7",
      "title": "Add Benzonase and Incubate",
      "instruction": "Add benzonase at a 1:1,000 dilution and incubate on a rotating platform at room temperature.",
      "expected_result": "Nucleic acids are digested, preparing the sample for pull-down assays."
    },
    {
      "id": "S16",
      "task_id": "T7",
      "title": "Centrifuge and Collect Supernatant for Pull Down",
      "instruction": "Centrifuge the sample at 16,000xg at 4°C for 10 minutes and transfer the supernatant to fresh tubes.",
      "expected_result": "Supernatant containing proteins is ready for pull-down assays."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Submit ethics application",
      "instruction": "Prepare and submit the ethics application to the Ethics Reviewing Board.",
      "expected_result": "Ethics application is submitted for review."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Receive ethics approval",
      "instruction": "Await and obtain approval from the Ethics Reviewing Board.",
      "expected_result": "Ethics approval is received."
    },
    {
      "id": "S3",
      "task_id": "T2",
      "title": "Collect biopsy specimens",
      "instruction": "Collect lung post-mortem biopsies from COVID-19 and non-COVID-19 patients.",
      "expected_result": "Biopsy specimens are collected and ready for processing."
    },
    {
      "id": "S4",
      "task_id": "T4",
      "title": "Fix and embed tissue samples",
      "instruction": "Fix the collected biopsies in 4% formaldehyde for three hours and embed them in paraffin.",
      "expected_result": "Tissue samples are fixed and embedded in paraffin."
    },
    {
      "id": "S5",
      "task_id": "T4",
      "title": "Cut tissue sections",
      "instruction": "Use a rotary microtome to cut 4-µm thick sections of the paraffin-embedded tissues.",
      "expected_result": "Tissue sections are cut and placed on Superfrost slides."
    },
    {
      "id": "S6",
      "task_id": "T11",
      "title": "Perform antigen retrieval",
      "instruction": "Immerse slides in antigen retrieval buffer and heat in a sterilizer for 10-15 minutes.",
      "expected_result": "Antigens are retrieved from the tissue sections."
    },
    {
      "id": "S7",
      "task_id": "T12",
      "title": "Permeabilize and block samples",
      "instruction": "Immerse slides in permeabilization buffer and incubate with blocking buffer for one hour.",
      "expected_result": "Samples are permeabilized and blocked to prevent nonspecific binding."
    },
    {
      "id": "S8",
      "task_id": "T6",
      "title": "Prepare primary staining mix",
      "instruction": "Prepare the primary staining mix with specified antibodies in blocking buffer.",
      "expected_result": "Primary staining mix is ready for application."
    },
    {
      "id": "S9",
      "task_id": "T6",
      "title": "Apply primary staining",
      "instruction": "Place the primary staining mix on the tissue sections and incubate for one hour.",
      "expected_result": "Tissue sections are stained with primary antibodies."
    },
    {
      "id": "S10",
      "task_id": "T7",
      "title": "Analyze stained samples",
      "instruction": "Use fluorescence microscopy to analyze the stained tissue sections.",
      "expected_result": "Images of stained samples are acquired for analysis."
    },
    {
      "id": "S11",
      "task_id": "T8",
      "title": "Quantify NET volume",
      "instruction": "Analyze Z-stack images to quantify the volume of NETs in lung tissue.",
      "expected_result": "Quantification of NET volume is completed."
    },
    {
      "id": "S12",
      "task_id": "T9",
      "title": "Perform statistical analysis",
      "instruction": "Conduct statistical analyses on the collected data to determine significance.",
      "expected_result": "Statistical analysis results are obtained."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Inoculate Salmonella cells",
      "instruction": "Pick a single colony of Salmonella cells and inoculate it into a glass test tube with LB media, shaking at 150 rpm at 30°C overnight.",
      "expected_result": "Overnight culture of Salmonella cells is prepared."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Transfer culture to fresh TB",
      "instruction": "Transfer 50 µl of overnight culture to 5 ml of fresh TB and incubate at 30°C with shaking until the cell density reaches an OD_600 of ca. 1.8.",
      "expected_result": "Salmonella cells are grown in fresh TB media."
    },
    {
      "id": "S3",
      "task_id": "T1",
      "title": "Add ampicillin",
      "instruction": "Add ampicillin to the culture at a final concentration of 100 µg/ml after reaching the desired OD.",
      "expected_result": "Ampicillin is incorporated into the culture for selection."
    },
    {
      "id": "S4",
      "task_id": "T6",
      "title": "Prepare cell suspension",
      "instruction": "Centrifuge 500 µl of culture to collect cells, discard supernatant, and resuspend the pellet in 1.0 ml of motility buffer.",
      "expected_result": "Cell suspension in motility buffer is ready for microscopy."
    },
    {
      "id": "S5",
      "task_id": "T6",
      "title": "Make tunnel slide",
      "instruction": "Prepare a tunnel slide by sandwiching double-sided tape between two coverslips.",
      "expected_result": "Tunnel slide is ready for cell attachment."
    },
    {
      "id": "S6",
      "task_id": "T6",
      "title": "Attach cells to slide",
      "instruction": "Add 50 µl of the cell suspension to the tunnel slide and leave for 5 minutes to allow attachment.",
      "expected_result": "Cells are attached to the coverslip surface."
    },
    {
      "id": "S7",
      "task_id": "T6",
      "title": "Wash unbound cells",
      "instruction": "Wash out unbound cells by adding 100 µl of motility buffer and absorb excess with filter paper.",
      "expected_result": "Unbound cells are removed, leaving only attached cells."
    },
    {
      "id": "S8",
      "task_id": "T11",
      "title": "Set up fluorescence microscope",
      "instruction": "Assemble the custom-built fluorescence microscope with the appropriate objective and lens.",
      "expected_result": "Fluorescence microscope is set up and ready for imaging."
    },
    {
      "id": "S9",
      "task_id": "T12",
      "title": "Capture fluorescence images",
      "instruction": "Capture images of pHluorin(M153R)-FliG fluorescent spots using the EMCCD camera with a 5 sec exposure time.",
      "expected_result": "Fluorescence images of the cells are captured."
    },
    {
      "id": "S10",
      "task_id": "T7",
      "title": "Measure cytoplasmic pH",
      "instruction": "Analyze the captured images to determine the local cytoplasmic pH using fluorescence intensity ratios.",
      "expected_result": "Cytoplasmic pH measurements are obtained from the images."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "task_id": "T3",
      "title": "Seed LUHMES cells",
      "instruction": "Seed proliferative LUHMES cells at 1.5×10^6 per T75 flask.",
      "expected_result": "LUHMES cells are seeded and ready for transduction."
    },
    {
      "id": "S2",
      "task_id": "T3",
      "title": "Transduce LUHMES cells",
      "instruction": "Transduce seeded LUHMES cells with GFP-expressing lentiviral particles for 24 hours at an appropriate MOI.",
      "expected_result": "LUHMES cells are transduced with GFP, achieving high transduction efficiency."
    },
    {
      "id": "S3",
      "task_id": "T3",
      "title": "Maintain LUHMES cells",
      "instruction": "After transduction, maintain cells in LUHMES Proliferation Media for 72 hours.",
      "expected_result": "LUHMES cells are maintained and ready for further experiments."
    },
    {
      "id": "S4",
      "task_id": "T4",
      "title": "Initiate differentiation",
      "instruction": "Change the media from LUHMES Proliferation Media to LUHMES Differentiation Media after 2-3 days of proliferation.",
      "expected_result": "LUHMES cells are now in differentiation media."
    },
    {
      "id": "S5",
      "task_id": "T4",
      "title": "Replate differentiating LUHMES cells",
      "instruction": "Replate differentiating LUHMES cells into a 384-well plate after 3 days in differentiation media.",
      "expected_result": "LUHMES cells are replated and ready for further analysis."
    },
    {
      "id": "S6",
      "task_id": "T5",
      "title": "Prepare co-culture",
      "instruction": "Seed astrocytes and LUHMES cells in a co-culture setup.",
      "expected_result": "Astrocytes and LUHMES cells are co-cultured for assessment."
    },
    {
      "id": "S7",
      "task_id": "T6",
      "title": "Wash astrocytes",
      "instruction": "Wash the astrocytes with sterile PBS to remove media.",
      "expected_result": "Astrocytes are washed and ready for lysis."
    },
    {
      "id": "S8",
      "task_id": "T6",
      "title": "Lyse astrocytes",
      "instruction": "Lyse the washed astrocytes to prepare for protein analysis.",
      "expected_result": "Astrocyte lysates are prepared for further analysis."
    },
    {
      "id": "S9",
      "task_id": "T7",
      "title": "Load protein samples",
      "instruction": "Load the prepared astrocyte lysates onto SDS-PAGE gels.",
      "expected_result": "Protein samples are loaded and ready for electrophoresis."
    },
    {
      "id": "S10",
      "task_id": "T7",
      "title": "Transfer proteins",
      "instruction": "Transfer proteins from the gel to membranes for detection.",
      "expected_result": "Proteins are transferred and ready for immunoblotting."
    },
    {
      "id": "S11",
      "task_id": "T8",
      "title": "Fix cells",
      "instruction": "Fix co-cultured cells with appropriate fixative.",
      "expected_result": "Cells are fixed and ready for staining."
    },
    {
      "id": "S12",
      "task_id": "T8",
      "title": "Stain cells",
      "instruction": "Stain fixed cells with specific antibodies to visualize target proteins.",
      "expected_result": "Cells are stained and ready for imaging."
    },
    {
      "id": "S13",
      "task_id": "T9",
      "title": "Add MTT solution",
      "instruction": "Add MTT solution to the wells to assess cell viability.",
      "expected_result": "MTT solution is added and cells are incubated for assessment."
    },
    {
      "id": "S14",
      "task_id": "T10",
      "title": "Fix and stain for neurite outgrowth",
      "instruction": "Fix and stain co-cultures to measure neurite lengths.",
      "expected_result": "Neurite outgrowth is visualized and ready for measurement."
    },
    {
      "id": "S15",
      "task_id": "T11",
      "title": "Sort cells by FACS",
      "instruction": "Sort astrocytes and LUHMES cells based on fluorescence and size using FACS.",
      "expected_result": "Cells are sorted and collected for further analysis."
    },
    {
      "id": "S16",
      "task_id": "T12",
      "title": "Process RNA for microarray",
      "instruction": "Extract RNA from sorted cells for microarray analysis.",
      "expected_result": "RNA is extracted and ready for gene expression analysis."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Isolate PBMCs",
      "instruction": "Isolate PBMCs from heparinized blood samples using density gradient centrifugation with Ficoll-Hypaque.",
      "expected_result": "PBMCs are isolated and ready for further processing."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Prepare PBMCs for MACS",
      "instruction": "Resuspend isolated PBMCs in 0.5% BSA-PBS buffer and determine the cell number.",
      "expected_result": "PBMCs are resuspended and cell number is quantified."
    },
    {
      "id": "S3",
      "task_id": "T1",
      "title": "Label PBMCs with Microbeads",
      "instruction": "Add appropriate Microbeads to the PBMC suspension and incubate.",
      "expected_result": "PBMCs are labeled with Microbeads for positive selection."
    },
    {
      "id": "S4",
      "task_id": "T1",
      "title": "Perform MACS separation",
      "instruction": "Use the MACS system to separate CD8+CD28− T cells from the labeled PBMCs.",
      "expected_result": "CD8+CD28− T cells are enriched and collected."
    },
    {
      "id": "S5",
      "task_id": "T1",
      "title": "Culture CD8+CD28− T cells",
      "instruction": "Seed CD8+CD28− T cells with B-APCs and cytokines in culture medium.",
      "expected_result": "CD8+CD28− T cells are cultured for 9 days."
    },
    {
      "id": "S6",
      "task_id": "T2",
      "title": "Prepare CFSE-labeled CD4+ T cells",
      "instruction": "Isolate and label A-CD4+ T cells with CFSE for proliferation analysis.",
      "expected_result": "CFSE-labeled A-CD4+ T cells are ready for coculture."
    },
    {
      "id": "S7",
      "task_id": "T2",
      "title": "Coculture CD4+ T cells with APCs",
      "instruction": "Coculture CFSE-labeled A-CD4+ T cells with B-APCs or I-APCs in the presence or absence of CD8+CD28− T cells.",
      "expected_result": "Coculture is established for 7 to 11 days."
    },
    {
      "id": "S8",
      "task_id": "T3",
      "title": "Analyze CFSE dilution",
      "instruction": "Perform flow cytometry to assess CFSE dilution in CD4+ T cells after coculture.",
      "expected_result": "Proliferation of CD4+ T cells is quantified based on CFSE dilution."
    },
    {
      "id": "S9",
      "task_id": "T4",
      "title": "Prepare cell mixture for injection",
      "instruction": "Mix responder CD4+ T cells with APCs and in vitro-expanded CD8+CD28− T cells.",
      "expected_result": "Cell mixture is prepared for injection into mice."
    },
    {
      "id": "S10",
      "task_id": "T4",
      "title": "Inject cell mixture into mice",
      "instruction": "Administer the cell mixture to NOG mice via intraperitoneal injection.",
      "expected_result": "Cells are successfully injected into the mice."
    },
    {
      "id": "S11",
      "task_id": "T5",
      "title": "Sacrifice mice and isolate spleen",
      "instruction": "Sacrifice the mice on day 11 post-injection and isolate the spleen.",
      "expected_result": "Spleen is collected for analysis."
    },
    {
      "id": "S12",
      "task_id": "T5",
      "title": "Analyze CD4+ T cells in spleen",
      "instruction": "Process the spleen to obtain a single-cell suspension and analyze CD4+ T cells by flow cytometry.",
      "expected_result": "Human CD4+ T cells in the spleen are quantified."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Sow seeds",
      "instruction": "Sow common bean ‘Black Valentine’ seeds in plastic pots filled with moisted vermiculite, placing the seeds just under the surface.",
      "expected_result": "Seeds are sown and covered with vermiculite."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Place pots in growth chamber",
      "instruction": "Put the pots in a tub full of tap water and place in a growth chamber at 23°C under a 16 h light/8 h dark cycle.",
      "expected_result": "Pots are in the growth chamber with appropriate environmental conditions."
    },
    {
      "id": "S3",
      "task_id": "T1",
      "title": "Water seedlings",
      "instruction": "Regularly fill the tub with tap water to maintain capillary watering approximately every two days.",
      "expected_result": "Seedlings are adequately watered and growing."
    },
    {
      "id": "S4",
      "task_id": "T1",
      "title": "Grow seedlings",
      "instruction": "Allow seedlings to grow for 10-12 days until primary leaves are fully expanded.",
      "expected_result": "Seedlings have developed fully expanded primary leaves."
    },
    {
      "id": "S5",
      "task_id": "T2",
      "title": "Transplant seedlings",
      "instruction": "Transplant three seedlings into a larger pot filled with moisted vermiculite.",
      "expected_result": "Seedlings are successfully transplanted into larger pots."
    },
    {
      "id": "S6",
      "task_id": "T2",
      "title": "Place in dark room",
      "instruction": "Place the transplanted pots in a dark room at 19°C for 24 hours before inoculation.",
      "expected_result": "Seedlings are acclimatized in the dark room."
    },
    {
      "id": "S7",
      "task_id": "T4",
      "title": "Prepare DNA plasmid mix",
      "instruction": "Mix the appropriate BPMV plasmids in a final volume of 20 µL of 50 mM potassium phosphate buffer in an Eppendorf tube.",
      "expected_result": "DNA plasmid mix is prepared for inoculation."
    },
    {
      "id": "S8",
      "task_id": "T4",
      "title": "Powder leaf with carborundum",
      "instruction": "Powder the upper surface of one primary leaf per plant with carborundum.",
      "expected_result": "Leaf surface is dusted with carborundum."
    },
    {
      "id": "S9",
      "task_id": "T4",
      "title": "Apply DNA plasmid mix",
      "instruction": "Using a pipetman, place the DNA plasmid mix on the upper leaf surface at the junction between petiole and blade.",
      "expected_result": "DNA plasmid mix is applied to the leaf surface."
    },
    {
      "id": "S10",
      "task_id": "T4",
      "title": "Rub leaf surface",
      "instruction": "Rub the leaf surface with a gloved finger to spread the DNA plasmid mix evenly.",
      "expected_result": "Leaf surface is evenly rubbed with the DNA plasmid mix."
    },
    {
      "id": "S11",
      "task_id": "T4",
      "title": "Rinse inoculated leaf",
      "instruction": "At 3-4 minutes after rubbing, rinse the inoculated leaf with tap water until all carborundum is removed.",
      "expected_result": "Inoculated leaf is rinsed clean of carborundum."
    },
    {
      "id": "S12",
      "task_id": "T4",
      "title": "Remove excess water",
      "instruction": "Gently remove excess water from the upper side of the leaf using absorbent paper.",
      "expected_result": "Excess water is absorbed without damaging the leaf."
    },
    {
      "id": "S13",
      "task_id": "T4",
      "title": "Place inoculated plants in growth chamber",
      "instruction": "Place the inoculated plants in a growth chamber at 19°C under a 16 h light/8 h dark cycle.",
      "expected_result": "Inoculated plants are in the growth chamber under specified conditions."
    },
    {
      "id": "S14",
      "task_id": "T5",
      "title": "Examine GFP expression",
      "instruction": "Use UV light to examine GFP expression in the primary leaves and capture images with a digital camera.",
      "expected_result": "Images of GFP expression are captured."
    },
    {
      "id": "S15",
      "task_id": "T10",
      "title": "Photograph GFP expression",
      "instruction": "Examine GFP expression in aerial organs and roots using a UV lamp and photograph the results.",
      "expected_result": "Photographs of GFP expression in various plant parts are obtained."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Collect Blood Samples",
      "instruction": "Collect blood samples from patients meeting WHO criteria for SARS.",
      "expected_result": "166 blood samples are collected from 41 patients covering acute, convalescent, and recovered phases."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Label Samples",
      "instruction": "Label each blood sample appropriately for tracking and identification.",
      "expected_result": "All samples are labeled and organized for further processing."
    },
    {
      "id": "S3",
      "task_id": "T2",
      "title": "Clone ACE2 Gene",
      "instruction": "Clone the ACE2 gene from a human kidney cDNA library.",
      "expected_result": "ACE2 gene is successfully cloned and ready for transfection."
    },
    {
      "id": "S4",
      "task_id": "T2",
      "title": "Transfect QT6 Cells",
      "instruction": "Transfect QT6 cells with the cloned ACE2 gene to create an ACE2-positive cell line.",
      "expected_result": "QT6 cells are transfected and selected for ACE2 expression."
    },
    {
      "id": "S5",
      "task_id": "T3",
      "title": "Seed 293T Cells",
      "instruction": "Subculture 293T/17 cells into 6-well plates to achieve 70-90% confluence.",
      "expected_result": "293T cells are seeded and reach the desired confluence by the time of transfection."
    },
    {
      "id": "S6",
      "task_id": "T3",
      "title": "Prepare Transfection Mix",
      "instruction": "Prepare the transfection mix by combining plasmid constructs and PEI in Opti-MEM.",
      "expected_result": "Transfection mix is prepared and incubated at room temperature."
    },
    {
      "id": "S7",
      "task_id": "T3",
      "title": "Transfect Cells",
      "instruction": "Add the transfection mix dropwise to the 293T cells and swirl gently.",
      "expected_result": "Transfection mix is evenly distributed across the cells."
    },
    {
      "id": "S8",
      "task_id": "T3",
      "title": "Harvest Supernatant",
      "instruction": "Harvest the supernatant containing viral pseudotype particles after 48 hours.",
      "expected_result": "Supernatant is collected and filtered for downstream applications."
    },
    {
      "id": "S9",
      "task_id": "T4",
      "title": "Infect Target Cells",
      "instruction": "Infect 293T, TE671, and QT6/ACE2 cells with the harvested supernatant.",
      "expected_result": "Target cells are infected with the viral supernatant for titer measurement."
    },
    {
      "id": "S10",
      "task_id": "T5",
